<script setup lang="ts">
import { onMounted } from 'vue'; import { storeToRefs } from 'pinia'; import { useRouter } from 'vue-router'; import PageHeader from '@/Components/layout/PageHeader.vue'; import QrCodeCard from '@/Components/sites/QrCodeCard.vue'; import { useSiteQrCode } from '@/composables/useSiteQrCode'; import { useAdministratorStore } from '@/stores/administrator.store'; import { useUiFeedbackStore } from '@/stores/ui-feedback.store'
const router = useRouter(); const store = useAdministratorStore(); const feedback = useUiFeedbackStore(); const { sites, isSitesLoading } = storeToRefs(store); const { generatingId, generate } = useSiteQrCode()
onMounted(async () => { try { await store.loadSites() } catch { feedback.error('Impossible de charger les sites.') } })
</script>
<template><div class="mx-auto w-full max-w-[1440px]"><PageHeader><template #title>QR codes des sites</template><template #description>Consultez et renouvelez les identifiants de pointage de chaque site.</template><template #actions><v-btn color="primary" prepend-icon="mdi-map-marker-plus-outline" :to="{ name: 'admin-site-create' }">Nouveau site</v-btn></template></PageHeader><v-alert class="mb-6" type="info" variant="tonal" text="La régénération invalide l’ancien QR code. L’image n’est affichée qu’au moment de sa génération : pensez à l’imprimer." /><v-progress-linear v-if="isSitesLoading" indeterminate color="primary" class="mb-4" /><div class="grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><QrCodeCard v-for="site in sites" :key="site.id" :site="site" :loading="generatingId === site.id" @details="router.push({ name: 'admin-site-details', params: { siteId: $event.id } })" @regenerate="generate" /></div></div></template>
